    yi: ['相见的机会难得，分别时更是难舍难分，何况又是春风无力、百花凋零的暮春时节。', '春蚕到死的时候才吐完它的丝，蜡烛烧成灰的时候蜡泪才流干。', '早晨照镜子，只担心如云的鬓发改变了颜色；夜里吟诗，想来你也会觉得月光清冷。', '你住的蓬莱山离这里没有多远，就请青鸟殷勤地替我去探望吧。'],
