    yi: [
      '航海的人谈起瀛洲，说它隐没在烟雾笼罩的波涛里，实在难以找到；',
      '越地的人说起天姥山，说它在忽明忽暗的云霞里，有时还能看见。',
      '天姥山高耸入天，横在天边，山势超过五岳，压倒了赤城山。',
      '高达四万八千丈的天台山，对着天姥山，也好像要倒向东南方。',
      '我根据越人的话，梦游吴越，一夜之间飞过了映着明月的镜湖。',
      '湖上的月光照着我的身影，一直送我到了剡溪。',
      '谢灵运住过的地方如今还在，清澈的溪水荡漾，猿猴的叫声凄清。',
      '我脚穿谢公当年的木屐，登上直入云霄的山路。',
      '在半山腰看见海上升起的太阳，在空中听见天鸡的啼叫。',
      '山路在千山万岩之间盘旋，方向不定，我迷恋着山花，靠着岩石歇息，忽然天色已经暗了。',
      '熊在咆哮，龙在吟啸，声音在山岩泉水之间震响，让深林战栗，让层层山峰震惊。',
      '乌云黑沉沉的，像要下雨，水波荡漾，升起了烟雾。',
      '电光闪闪，雷声隆隆，山峰好像要崩塌了。',
      '仙府的石门，轰隆一声从中间打开。',
      '里面的青天广阔无边，望不到底，日月照耀着金银砌成的宫阙。',
      '仙人们用彩虹做衣服，把风当作马，云中的神仙纷纷降落下来。',
      '老虎弹着瑟，鸾鸟驾着车，仙人们一排排地站着，密密麻麻。',
      '忽然我心惊魂动，猛然惊醒，不禁长声叹息。',
      '醒来时只看到身边的枕头和席子，刚才梦里的烟霞仙境全都消失了。',
      '人世间的欢乐也像这梦境一样，自古以来，万事都像东流的水一样一去不返。',
      '告别各位朋友，我什么时候才能回来呢？暂且把白鹿放在青山之间，要走的时候就骑上它去访问名山。',
      '怎么能低头弯腰去侍奉那些权贵，让我心里不痛快呢！',
    ],
    bg: '天宝三载（744年），李白被唐玄宗「赐金放还」，离开了长安。第二年他要从东鲁（今山东）南游吴越，写了这首诗留别东鲁的朋友。这首诗一题作《梦游天姥山别东鲁诸公》。',
