    bg: '大历三年（768年）冬天，杜甫离开四川，坐船漂泊到岳州（今湖南岳阳），登上了向往已久的岳阳楼。那时他五十七岁，又老又病，一家人住在船上，北方还在打仗。两年后，他就在湘江的船上去世了。',
