    yi: ['柳州城上的高楼远远连着荒远的原野，我的愁思像海天一样茫茫无边。', '急风乱吹着长满荷花的水面，密雨斜打着爬满薜荔的墙。', '五岭的树木重重遮住了远望的视线，江水弯弯曲曲，像我百转的愁肠。', '我们一起来到这南方百越的文身之地，却还是书信不通，各自滞留一方。'],
    bg: '永贞元年（805年），柳宗元、刘禹锡等人参加王叔文的政治改革，失败后都被贬到远方。元和十年（815年），他们被召回长安，不久又被贬为更远的边州刺史，柳宗元到了柳州。他登上柳州城楼，想起同样被贬的四位朋友，写了这首诗寄给他们。',
