    yi: ['人生在世，朋友常常不能相见，就像参星和商星一样，此出彼没。', '今晚是个什么样的好日子啊，我们竟能一起在这灯光下相聚！', '年轻力壮的时光能有多久？我们的鬓发都已经花白了。', '打听老朋友，一半已经去世，我惊呼起来，心里十分激动。', '哪里想到隔了二十年，我又一次来到你的家。', '当年分别时你还没有结婚，如今儿女已经一大群了。', '他们高高兴兴地招呼父亲的老朋友，问我从哪里来。', '问答还没有说完，你就打发儿女去摆上酒菜。', '冒着夜雨割来春天的韭菜，刚煮好的饭里掺着黄米。', '主人说见一面太难了，一举杯就接连喝了十杯。', '喝了十杯也没有醉，我感激你老朋友的深长情意。', '明天我们又要隔着山岳，各在一方，彼此的命运都难以预料了。'],
