    yi: ['有一位当世无双的美人，隐居在空寂的山谷里。', '她说自己本是好人家的女儿，如今飘零沦落，住在山野草木之间。', '从前关中遭遇战乱，她的兄弟都被杀害了。', '官职再高又有什么用？连兄弟的尸骨都没法收殓。', '世态人情都厌恶衰败的人家，世事就像随风转动的烛火一样变化无常。', '她的丈夫是个轻薄的人，又娶了一个美貌如玉的新人。', '合欢花尚且知道早开晚合，鸳鸯也总是成双成对，从不独宿。', '丈夫只看见新人的笑脸，哪里听得见旧人的哭声？', '泉水在山里是清的，流出山就变浊了。', '丫鬟卖了珠宝回来，拉来藤萝修补漏雨的茅屋。', '摘了花也不插在头上，采来柏枝，常常满满一捧。', '天气寒冷，她穿着单薄的翠袖，傍晚时靠着修长的竹子。'],
