    yi: ['主人备了酒，今晚大家尽欢，请那位像广陵客一样的琴师弹奏鸣琴。', '月光照着城头，乌鸦有的已经飞散，寒霜凄冷，万树萧瑟，风吹进了衣裳。', '铜炉里焚着香，华美的蜡烛越发明亮，琴师先弹《渌水》，后弹《楚妃》。', '琴声一响，万物都静了下来，四座的人默默无言，星星也快要稀少了。', '我要奉命出使到千里之外的淮水，冒昧地说一句：我归隐云山的心意，就从听这琴声开始了。'],
    bg: '从诗里「清淮奉使千余里」看，李颀当时将要奉命出使到淮水一带，在主人为他摆的酒宴上听琴，写了这首诗。具体是哪一年不清楚。',
